1	/**
2	 * `@pantoken/demo` — the render side of the `@demo` system.
3	 *
4	 * `@pantoken/typedoc-plugin-demo` turns a `@demo <spec>` tag into a fenced ```demo``` block whose
5	 * body is the spec (a bare URL or a `<provider>:<ref>` pair). This package resolves that spec into an
6	 * embeddable iframe and renders the surrounding panel — an MDN-style "live sample."
7	 *
8	 * It ships three things: {@link resolveDemo} (spec → iframe attributes, framework-agnostic), a
9	 * markdown-it plugin ({@link demoMarkdownIt}) that turns ```demo``` fences into the panel HTML, and a
10	 * self-hosted runner (`@pantoken/demo/runner.html`) — a same-origin page that fetches a bare
11	 * HTML/CSS/JS demo and renders it with your token stylesheets injected, so `self:` demos need no
12	 * third-party account and no framing workarounds.
13	 *
14	 * @example
15	 * ```ts
16	 * import { resolveDemo } from "@pantoken/demo";
17	 *
18	 * resolveDemo("stackblitz:abc123").src; // → "https://stackblitz.com/edit/abc123?embed=1&…"
19	 * resolveDemo("self:button", { base: "/docs/", cssUrls: ["/docs/tokens.css"] }).src;
20	 * ```
21	 *
22	 * @module
23	 */
24	import type MarkdownIt from "markdown-it";
25	
26	/** Options for resolving a demo spec. Only the `self` provider uses the runner/demos/css fields. */
27	export interface ResolveOptions {
28	  /** Site base path, e.g. `/pantoken/` (default `/`). */
29	  base?: string;
30	  /** Runner page path, relative to `base` (default `play/index.html`). */
31	  runnerPath?: string;
32	  /** Self-hosted demo-source dir, relative to `base` (default `demos/`). */
33	  demosPath?: string;
34	  /**
35	   * Stylesheet URLs the runner injects (into its chrome and every rendered result): the component
36	   * sheets, the multi-theme token sheet, and the plugin/surface sheets. The runner themes by toggling
37	   * the `data-pantoken-theme` attribute, so one token sheet covers every theme.
38	   */
39	  cssUrls?: readonly string[];
40	}
41	
42	/** A resolved demo: iframe attributes plus the provider that produced them. */
43	export interface ResolvedDemo {
44	  /** The provider that produced the embed (`url`, `self`, `stackblitz`, …). */
45	  provider: string;
46	  /** The iframe `src`. */
47	  src: string;
48	  /** The iframe `sandbox` attribute. */
49	  sandbox: string;
50	}
51	
52	const SANDBOX = "allow-scripts allow-same-origin allow-forms allow-popups allow-modals";
53	
54	/**
55	 * Resolve a `@demo` spec into iframe attributes.
56	 *
57	 * @param spec - A bare URL/path, or `<provider>:<ref>`.
58	 * @param options - {@link ResolveOptions}.
59	 * @returns The {@link ResolvedDemo}.
60	 *
61	 * @example Provider specs
62	 * ```ts
63	 * resolveDemo("https://example.com/x").provider; // "url"
64	 * resolveDemo("codepen:team/abc123").src; // "https://codepen.io/team/embed/abc123?default-tab=result"
65	 * ```
66	 * @module
67	 * @beta
68	 */
69	export function resolveDemo(spec: string, options: ResolveOptions = {}): ResolvedDemo {
70	  const trimmed = spec.trim();
71	
72	  // A bare URL or root-relative path is a raw iframe src (also stops `https:` reading as a provider).
73	  if (/^(https?:\/\/|\/)/.test(trimmed)) {
74	    return { provider: "url", src: trimmed, sandbox: SANDBOX };
75	  }
76	
77	  const match = /^([a-z][a-z0-9-]*):(.*)$/is.exec(trimmed);
78	  const provider = match ? match[1].toLowerCase() : "url";
79	  const ref = (match ? match[2] : trimmed).trim();
80	
81	  switch (provider) {
82	    case "self": {
83	      // Target the runner file explicitly (an SPA host may serve its own shell for the bare dir URL).
84	      const runner = `${options.base ?? "/"}${options.runnerPath ?? "play/index.html"}`;
85	      const demos = `${options.base ?? "/"}${options.demosPath ?? "demos/"}`;
86	      const source = /^(https?:\/\/|\/)/.test(ref) ? ref : `${demos}${ref}.html`;
87	      const css = (options.cssUrls ?? []).join(",");
88	      const query =
89	        `?src=${encodeURIComponent(source)}` + (css ? `&css=${encodeURIComponent(css)}` : "");
90	      return { provider, src: `${runner}${query}`, sandbox: SANDBOX };
91	    }
92	    case "stackblitz": {
93	      const path = /^(github|edit)\//.test(ref) ? ref : `edit/${ref}`;
94	      return {
95	        provider,
96	        src: `https://stackblitz.com/${path}?embed=1&view=preview&hideNavigation=1`,
97	        sandbox: SANDBOX,
98	      };
99	    }
100	    case "codesandbox":
101	      return {
102	        provider,
103	        src: `https://codesandbox.io/embed/${ref}?view=preview`,
104	        sandbox: SANDBOX,
105	      };
106	    case "codepen": {
107	      const [user, slug] = ref.split("/");
108	      return {
109	        provider,
110	        src: `https://codepen.io/${user}/embed/${slug}?default-tab=result`,
111	        sandbox: SANDBOX,
112	      };
113	    }
114	    case "dartpad":
115	      return {
116	        provider,
117	        src: `https://dartpad.dev/embed-flutter.html?id=${ref}`,
118	        sandbox: SANDBOX,
119	      };
120	    case "wp-playground":
121	      return {
122	        provider,
123	        src: `https://playground.wordpress.net/?mode=seamless&blueprint-url=${encodeURIComponent(ref)}`,
124	        sandbox: SANDBOX,
125	      };
126	    default:
127	      // Unknown provider: treat the whole spec as a URL.
128	      return { provider: "url", src: trimmed, sandbox: SANDBOX };
129	  }
130	}
