132	/** Escape a string for use in an HTML attribute. */
133	const escapeAttr = (value: string): string =>
134	  value.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
