136	/**
137	 * Render the demo panel HTML for a resolved demo: a bare, sandboxed, lazy-loaded iframe framed like a
138	 * live example (no host chrome — the runner inside carries its own tab toolbar). Style it with
139	 * `@pantoken/demo/demo.css`.
140	 *
141	 * @param resolved - A {@link ResolvedDemo}.
142	 * @returns The panel HTML string.
143	 */
144	export function renderDemoFigure(resolved: ResolvedDemo): string {
145	  const src = escapeAttr(resolved.src);
146	  return (
147	    `<figure class="pantoken-demo">` +
148	    `<iframe class="pantoken-demo__frame" src="${src}" title="Live demo" loading="lazy" sandbox="${escapeAttr(resolved.sandbox)}"></iframe>` +
149	    `</figure>\n`
150	  );
151	}
