153	/** How to seam a live preview onto each `@example` HTML fence on matching pages. */
154	export interface LiveExampleOptions {
155	  /** Only wrap fences on pages whose markdown-it `env.relativePath` matches (e.g. the CSS-API pages). */
156	  match: (relativePath: string) => boolean;
157	  /** Build the preview block appended after each non-overlay ` ```html ` fence, from its markup. */
158	  wrap: (html: string) => string;
159	}
160	
161	/** Options for {@link demoMarkdownIt}: the {@link resolveDemo} fields plus optional live-example seaming. */
162	export interface DemoMarkdownItOptions extends ResolveOptions {
163	  /**
164	   * When set, appends a live preview after each ` ```html ` fence on matching pages — the same markup,
165	   * rendered live, beneath its source. Overlay examples (`<dialog>`, `[popover]`) are skipped: they're
166	   * hidden until opened, so a `## Demo` iframe drives their preview instead.
167	   */
168	  liveExample?: LiveExampleOptions;
169	}
170	
171	/** An example that's hidden until opened (a `<dialog>` or a `[popover]`), so its live preview is skipped. */
172	function isOverlay(html: string): boolean {
173	  return /^<dialog\b/u.test(html.trim()) || /\spopover(?:=|\s|>)/u.test(html);
174	}
175	
176	/**
177	 * A markdown-it plugin: turn ```demo``` fences into the demo panel. Use it with
178	 * `md.use(demoMarkdownIt, options)`.
179	 *
180	 * @param md - The markdown-it instance.
181	 * @param options - {@link DemoMarkdownItOptions}.
182	 *
183	 * @example
184	 * ```ts
185	 * import MarkdownIt from "markdown-it";
186	 * import { demoMarkdownIt } from "@pantoken/demo";
187	 *
188	 * const md = new MarkdownIt().use(demoMarkdownIt, {
189	 *   base: "/pantoken/",
190	 *   cssUrls: ["/pantoken/demos-assets/tokens.css", "/pantoken/demos-assets/components.css"],
191	 * });
192	 * ```
193	 */
194	export function demoMarkdownIt(md: MarkdownIt, options: DemoMarkdownItOptions = {}): void {
195	  const fence = md.renderer.rules.fence;
196	  if (!fence) return;
197	
198	  md.renderer.rules.fence = (...args) => {
199	    const [tokens, index, , env] = args;
200	    const token = tokens[index];
201	    const info = token.info.trim();
202	    if (info === "demo") {
203	      return renderDemoFigure(resolveDemo(token.content.trim(), options));
204	    }
205	    const rendered = fence(...args);
206	    // Seam a live preview onto each `@example` HTML fence on matching pages (the CSS-API pages load the
207	    // component CSS, so the same markup renders live). The rendered source fence stays as-is above it.
208	    const live = options.liveExample;
209	    if (live && info === "html") {
210	      const relativePath = (env as { relativePath?: string } | undefined)?.relativePath ?? "";
211	      const html = token.content.replace(/\n$/u, "");
212	      if (live.match(relativePath) && !isOverlay(html)) {
213	        return `${rendered}\n${live.wrap(html)}\n`;
214	      }
215	    }
216	    return rendered;
217	  };
218	}
