/**
 * A markdown-it plugin that renders a live preview beneath any inline code span whose value carries a
 * `data:image/…` URI — the image tokens in the CSS API tables (icons as `;utf8,` percent-encoded
 * SVGs, logos as `;base64,` SVGs, component-helper masks). It decodes the data URI back to inline SVG
 * and drops it on its own line under the raw value, so the reader sees what the token paints instead
 * of an unreadable encoded string.
 *
 * Inlining (rather than an `<img src>`) lets `currentColor` icons inherit the theme text color, so
 * they stay visible in both light and dark. Detection is content-based, so it covers every table
 * shape at once (tokens-consumed `Value` cells, the logos `Default` column, the `hu/` locale clones)
 * with no per-page wiring. Styled by `.pantoken-token-preview` in the docs theme's `pantoken.css`.
 *
 * @module
 */
import type MarkdownIt from "markdown-it";

/** The first `data:image/…` URI inside a code span (unwrapped from any `url("…")`), or null. */
function findDataImage(content: string): string | null {
  return /data:image\/[^\s'")]+/i.exec(content)?.[0] ?? null;
}

/** A decoded data URI: `svg` for inline SVG markup, or `src` to fall back to an `<img>`. */
interface DecodedImage {
  svg?: string;
  src?: string;
}

/**
 * Decode a `data:image/…` URI. SVG payloads (`;base64,` or percent-encoded `;utf8,`/bare) decode to
 * inline markup; any other image type falls back to the raw URI as an `<img src>`.
 */
function decodeDataImage(uri: string): DecodedImage {
  const match = /^data:([^,]*),([\s\S]*)$/.exec(uri);
  if (!match) return {};
  const [, meta, data] = match;
  if (!/^image\/svg\+xml/i.test(meta)) return { src: uri };
  try {
    if (/;base64/i.test(meta)) return { svg: Buffer.from(data, "base64").toString("utf8") };
    return { svg: decodeURIComponent(data) };
  } catch {
    return { src: uri };
  }
}

/** Strip script elements, inline event handlers, and `javascript:` refs before inlining the SVG. */
function sanitizeSvg(svg: string): string {
  return svg
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, "")
    .replace(/\son\w+\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi, "")
    .replace(/\s(?:xlink:href|href)\s*=\s*("javascript:[^"]*"|'javascript:[^']*')/gi, "");
}

/** Escape a string for use in a double-quoted HTML attribute. */
function escapeAttr(value: string): string {
  return value.replace(/&/g, "&amp;").replace(/"/g, "&quot;");
}

/**
 * Register the plugin: `md.use(tokenImagePreview)`. Wraps the default `code_inline` renderer and, when
 * the code span holds a `data:image/…` value, appends a `.pantoken-token-preview` block after it.
 */
export function tokenImagePreview(md: MarkdownIt): void {
  const defaultRender =
    md.renderer.rules.code_inline ??
    ((tokens, index, options, _env, self) => self.renderToken(tokens, index, options));

  md.renderer.rules.code_inline = (tokens, index, options, env, self) => {
    const rendered = defaultRender(tokens, index, options, env, self);
    const uri = findDataImage(tokens[index].content);
    if (!uri) return rendered;

    const { svg, src } = decodeDataImage(uri);
    let inner: string;
    if (svg) inner = sanitizeSvg(svg);
    else if (src) inner = `<img src="${escapeAttr(src)}" alt="" />`;
    else return rendered;

    return `${rendered}<span class="pantoken-token-preview" role="img" aria-label="token preview">${inner}</span>`;
  };
}

