/* Image-valued tokens in the CSS API tables (icons, logos, mask helpers) carry a `data:image` URI as
   their raw value. `tokenImagePreview` (a markdown-it plugin) decodes it back to inline SVG and drops
   it here, on its own line below the value. The box carries `color: var(--vp-c-text-1)` so
   `currentColor` icons resolve to the theme text colour and stay visible in light and dark; the SVG is
   capped so wide logos don't overflow the table cell. */
.pantoken-token-preview {
  display: block;
  margin-block-start: 6px;
  padding: 6px 8px;
  border: 1px solid var(--vp-c-divider);
  border-radius: 6px;
  background: var(--vp-c-bg-soft);
  color: var(--vp-c-text-1);
  line-height: 0;
}

.pantoken-token-preview :is(svg, img) {
  width: auto;
  height: auto;
  max-width: 100%;
  max-height: 3rem;
}

